"""Classification of the alignment classes by the radial invariant.

Two nodes z(m,n) = (n+i)/m and z(m',n') are exactly hyperbolically collinear with the
base point i if and only if their radial invariants agree:

    rho(m, n) = (m^2 - n^2 - 1) / (m n).

So the entire line structure of the picture is recovered by reducing one fraction per
seed and bucketing.  For all seeds with m <= M there are Theta(M^2) seeds and the cost
is O(M^2 log M), the logarithm coming from the gcd reductions.  No geometry, no floating
point, and no collinearity test is ever evaluated.
"""

from __future__ import annotations

import math
from fractions import Fraction
from math import gcd
from typing import Dict, List, Tuple

Seed = Tuple[int, int]


def is_seed(m: int, n: int) -> bool:
    return 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def radial(m: int, n: int) -> Fraction:
    """The radial invariant (m^2 - n^2 - 1)/(m n), automatically in lowest terms."""
    return Fraction(m * m - n * n - 1, m * n)


def dist_base(m: int, n: int) -> float:
    """Hyperbolic distance from the centre: arcosh((m^2 + n^2 + 1)/(2m))."""
    return math.acosh((m * m + n * n + 1.0) / (2.0 * m))


def alignment_classes(m_max: int) -> Dict[Fraction, List[Seed]]:
    """Bucket every Euclid seed with m <= m_max by its radial invariant."""
    classes: Dict[Fraction, List[Seed]] = {}
    for m in range(2, m_max + 1):
        for n in range(1, m):
            if is_seed(m, n):
                classes.setdefault(radial(m, n), []).append((m, n))
    for members in classes.values():
        members.sort()
    return classes


def discriminant(rho: Fraction) -> int:
    """The discriminant a^2 + 4 b^2 of the line rho = a/b; never a perfect square."""
    return rho.numerator ** 2 + 4 * rho.denominator ** 2


def largest_classes(m_max: int, top: int = 8) -> List[Tuple[Fraction, List[Seed]]]:
    classes = alignment_classes(m_max)
    return sorted(classes.items(), key=lambda kv: (-len(kv[1]), kv[0]))[:top]


if __name__ == "__main__":
    for rho, members in largest_classes(1500, 8):
        gaps = [dist_base(*q) - dist_base(*p) for p, q in zip(members, members[1:])]
        print(f"rho = {str(rho):>6}  disc = {discriminant(rho):>6}  "
              f"{len(members)} seeds: {members}")
        if gaps:
            print("        distance gaps along the line: "
                  + ", ".join(f"{g:.5f}" for g in gaps))
